{
  "findings": [
    {
      "check_id": "CKV_GCP_29",
      "title": "Uniform bucket-level access is not enabled",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "The bucket does not enable uniform bucket-level access, allowing legacy object ACLs to create inconsistent or unintended access paths."
    },
    {
      "check_id": "CKV_GCP_114",
      "title": "Public access prevention is not enforced",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "The bucket does not explicitly enforce public access prevention, so a later IAM or ACL change could expose compliance data publicly."
    },
    {
      "check_id": "CKV_GCP_62",
      "title": "Bucket access logging is not enabled",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "The compliance bucket has no access logging configuration, reducing visibility into access to stored trading-platform compliance data."
    }
  ],
  "patched_code": "resource "google_storage_bucket" "compliance_storage" {
  name                        = "${var.project_id}-digital-asset-trading-platform-compliance"
  location                    = var.region
  uniform_bucket_level_access = true
  public_access_prevention    = "enforced"

  logging {
    log_bucket        = "${var.project_id}-digital-asset-trading-platform-compliance"
    log_object_prefix = "access-logs/"
  }

  versioning {
    enabled = true
  }

  lifecycle_rule {
    condition {
      age = 2555
    }
    action {
      type = "Delete"
    }
  }
}

resource "google_storage_bucket_iam_member" "compliance_log_writer" {
  bucket = google_storage_bucket.compliance_storage.name
  role   = "roles/storage.objectCreator"
  member = "group:cloud-storage-analytics@google.com"
}
",
  "fix_summary": "Enabled uniform bucket-level access and enforced public access prevention. Configured access logs to be stored under a dedicated prefix in the bucket and granted the Cloud Storage analytics delivery group permission to create those log objects."
}
